# Taboo Jr. — kid-friendly word-guessing game.
#
# The game is one self-contained HTML file (index.html, generated by
# build.py), so this serves it as-is rather than as a template.

from pathlib import Path
from flask import Blueprint, send_from_directory

taboo_jr = Blueprint("taboo_jr", __name__)

HERE = Path(__file__).parent


@taboo_jr.route("/taboo-jr")
def index():
    return send_from_directory(HERE, "index.html")
